// A title attribute is not an explanation on a phone. Measured on this cut:
// 4,633 of the 7,680 rows carry a dashed GRID and SUB, and 26 carry NO MAP
// instead of a map link. Every one of those non-answers keeps its reason in a
// title attribute. The pain log of 2026-09-03, taken at 393x852 with
// matchMedia("(pointer: coarse)") true and "(hover: hover)" false, counted 56
// of the 100 rows on the default view showing GRID - and SUB -, tapped one,
// and got nothing: "A dash with no reachable explanation reads as broken, not
// as not known." NO MAP additionally sets cursor: not-allowed, which a device
// with no cursor cannot show either.
//
// So the explanation is printed, in the cell, when the chip is tapped. The
// title attribute is left exactly where it is: a mouse keeps the hover it
// always had, and this is the same sentence by another route rather than a
// second, drifting copy of it. textContent, so the string cannot become markup.
function revealExplanation(chip) {
  const existing = chip.nextElementSibling;
  if (existing && existing.classList.contains("action-explain")) {
    existing.remove();
    chip.setAttribute("aria-expanded", "false");
    return;
  }
  const cell = chip.parentElement;
  if (cell) {
    for (const other of cell.querySelectorAll(".action-explain")) other.remove();
    for (const other of cell.querySelectorAll("[aria-expanded=\"true\"]")) {
      other.setAttribute("aria-expanded", "false");
    }
  }
  const note = document.createElement("p");
  note.className = "action-explain";
  note.textContent = chip.getAttribute("title") || "";
  chip.insertAdjacentElement("afterend", note);
  chip.setAttribute("aria-expanded", "true");
}

